mapper.select:
SELECT A.ENTRUST_STATUS AS entrustStatus, A.PRICE * 100 AS price, ROUND(NVL(T5.FINISH_AMT,0)/(A.ENTRUST_AMT),4)*100 AS transactioncom, ROUND(NVL(IQC.totalShareAmt,0)/(A.ENTRUST_AMT),4)*100 AS tradeFinishPercent, A.INV_MANAGER_ID AS invManagerId, (SELECT real_name FROM SYS_USER WHERE user_name = A.INV_MANAGER_ID) AS invManagerName, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, C.SEC_ACCT_ID AS secAcctId, D.SEC_ACCT_NAME AS secAcctName, A.PS AS ps, A.CCY AS ccy, NVL(T1.PARTY_ID,A.COUNTER_ID) AS counterId, A.COUNTER_TRADER AS counterTrader, A.ENTRUST_AMT AS entrustNum, NVL(T5.FINISH_AMT,0) AS finishAmt, (A.ENTRUST_AMT -NVL(T5.FINISH_AMT,0) ) AS avaNum, A.VDATE AS vdate, A.MDATE AS mdate, C.VDATE AS repoVdate, C.MDATE AS repoMdate, C.TERM_DAYS AS term, A.ENTRUST_ID AS entrustId, NVL2(C.SETTLE_SPREED, CONCAT('0',C.SETTLE_SPREED+1), NULL) AS settleSpreed, NVL(F.PARTY_ID, FF.PARTY_ID) AS mySide, NVL(G.PARTY_ABBR, GG.PARTY_ABBR) AS mySideAbbr, (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = NVL(G.PARTY_ID, GG.PARTY_ID) OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = NVL(G.PARTY_ID, GG.PARTY_ID)) ) AS mySideTrader ,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = nvl(G.PARTY_ID, GG.PARTY_ID) OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = nvl(G.PARTY_ID, GG.PARTY_ID)) ) mySideTraderName, C.TERM_TYPE, A.VDATE vdate, pp.PORTFOLIO_SERIES portfolioSeries FROM ETR_ENTRUST A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS
where QUOTE_ID != #{currQuoteId}
GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO D ON C.SEC_ACCT_ID = D.SEC_ACCT_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
LEFT JOIN IBU_PORTFOLIO_ACCT_RELA F ON A.PORTFOLIO_ID = F.PORTFOLIO_ID AND F.CFETS_ACCT_TYPE = #{secAcctSource01} LEFT JOIN MST_CFETS_CUSTOMER_INFO G ON F.PARTY_ID = G.PARTY_ID
LEFT JOIN IBU_PORTFOLIO_ACCT_RELA FF ON A.PORTFOLIO_ID = FF.PORTFOLIO_ID AND FF.CFETS_ACCT_TYPE = #{secAcctSource02} LEFT JOIN MST_CFETS_CUSTOMER_INFO GG ON FF.PARTY_ID = GG.PARTY_ID LEFT JOIN SYS_USER H ON A.CREATE_USER = H.USER_NAME
LEFT JOIN (SELECT ENTRUST_ID,SUM(nvl(FPRICE_AMT,0)) totalShareAmt FROM IBU_QUOTE_CREP WHERE TRADE_STATUS = '07' GROUP BY ENTRUST_ID) IQC ON IQC.ENTRUST_ID = A.ENTRUST_ID
left join MST_CFETS_CUSTOMER_TRADER T2 ON T2.TRADER_ID = A.COUNTER_TRADER left join MST_CFETS_CUSTOMER_INFO T1 ON T1.PARTY_ID = T2.PARTY_ID LEFT JOIN PA_PTL_PORTFOLIO pp ON B.PORTFOLIO_ID = pp.PORTFOLIO_ID
where A.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple}) AND A.PS IN (#{ps03},#{ps04}) AND A.TRADE_MARKET = #{tradeMarket} AND A.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) AND E.TRADER = #{loginUserId}
AND A.ENTRUST_STATUS = #{entrustStatusUnAccept}
AND A.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < A.ENTRUST_AMT
AND ((A.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) >= A.ENTRUST_AMT) OR A.ENTRUST_STATUS = #{entrustStatusComple} )
AND A.PORTFOLIO_ID = #{portfolioId}
AND A.PORTFOLIO_ID IN
#{item}
AND C.TERM_DAYS = #{term}
AND DECODE(C.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}
AND A.PS = #{ps}
AND A.INV_MANAGER_ID IN
#{item}
and A.ENTRUST_ID in
#{item}
AND A.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
AND A.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') AND A.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND (H.USER_NAME LIKE '%'||#{keywords}||'%' OR A.PORTFOLIO_ID LIKE '%'||#{keywords}||'%' OR B.PORTFOLIO_NAME LIKE '%'||#{keywords}||'%' OR C.SEC_ACCT_ID LIKE '%'||#{keywords}||'%' OR A.PS LIKE '%'||#{keywords}||'%' OR A.VDATE LIKE '%'||#{keywords}||'%' OR A.MDATE LIKE '%'||#{keywords}||'%' OR A.ENTRUST_ID LIKE '%'||#{keywords}||'%')
and A.ENTRUST_ID not in
#{item}
order by A.PS,C.TERM_TYPE,C.SETTLE_SPREED,C.SEC_ACCT_ID desc

SELECT ETR_ENTRUST.ENTRUST_ID id, ETR_ENTRUST.ENTRUST_ID text FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD C ON ETR_ENTRUST.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON ETR_ENTRUST.ENTRUST_ID = E.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID WHERE ETR_ENTRUST.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
and ETR_ENTRUST.ENTRUST_ID = #{initValue}
AND E.TRADER = #{loginUserId} AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < ETR_ENTRUST.ENTRUST_AMT
and ETR_ENTRUST.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') and ETR_ENTRUST.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{search},'%'))
AND ETR_ENTRUST.PS = #{ps}
AND DECODE(C.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}

SELECT ETR_ENTRUST.ENTRUST_ID code, ETR_ENTRUST.ENTRUST_ID name FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD C ON ETR_ENTRUST.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON ETR_ENTRUST.ENTRUST_ID = E.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID WHERE ETR_ENTRUST.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
and ETR_ENTRUST.ENTRUST_ID = #{initValue}
AND E.TRADER = #{loginUserId} AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < ETR_ENTRUST.ENTRUST_AMT
and ETR_ENTRUST.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') and ETR_ENTRUST.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{search},'%'))
AND ETR_ENTRUST.PS = #{ps}
AND DECODE(C.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}

SELECT fp.FINPROD_ID AS finprodId, fp.FINPROD_MARKET_ID AS bondCode, fp.FINPROD_ABBR AS bondAbbrName, STL_SEC_ACCT_INFO.SEC_ACCT_NAME AS secAcctName, fp.IS_SUS AS isSus, fpa.IS_SEC_BOND AS isSecBond, fp.MDATE AS mdate, (NVL(ava.INAMOUNT, 0) - NVL(ava.OUTAMOUNT, 0)) * 100 AS prin, (NVL(avaExt.AMOUNT, 0) - NVL(pledgeExt.AMOUNT, 0)) * 100 AS avaPledgePrin, mbvi.NETPRICE AS netPrice, mbvi.VALUE_DATE AS valueDate, (SELECT MAX(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = fp.FINPROD_ID AND EXERCISE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd')) AS exerciseDate,
(SELECT NVL(SUM(NVL(b.PLEDGE_NUMBER, 0) * 100),0) FROM IBU_QUOTE_CREP a LEFT JOIN IBU_QUOTE_CREP_PLEDGE b ON a.QUOTE_ID = b.QUOTE_ID WHERE a.PORTFOLIO_ID = #{portfolioId} AND a.REPO_PS = #{ps03} AND b.PLEDGE_FINPROD_ID = fp.FINPROD_ID AND a.QUOTE_DATE = TO_DATE(#{platDate}, 'yyyy-MM-dd') AND (a.TRADE_STATUS IS NULL OR a.TRADE_STATUS NOT IN (#{tradeStatus15}, #{tradeStatus06}, #{tradeStatus08}, #{tradeStatus13}))
AND a.QUOTE_ID != #{quoteId}
) AS pledgeNumber,
(SELECT NVL(SUM(NVL(a.ENTRUST_NUM, 0) * -100),0) FROM ETR_ENTRUST a WHERE a.ps =#{psT02} AND a.PORTFOLIO_ID = #{portfolioId} AND a.FINPROD_ID = fp.FINPROD_ID AND a.VDATE = TO_DATE(#{platDate}, 'yyyy-MM-dd')) AS prinSysDate,
(NVL(ava2.INAMOUNT,0) - NVL(ava2.PLEDGEAMOUNT,0) - NVL(ava2.OUTAMOUNT,0)) * 100 AS avaPrinDayBefore,
(SELECT NVL(SUM(NVL(a.SHARE_AMT, 0) * -100),0) FROM TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID = b.TRADE_ID WHERE a.TRADE_DATE < TO_DATE(#{platDate}, 'yyyy-MM-dd') AND b.PORTFOLIO_ID = #{portfolioId} AND a.FINPROD_ID = fp.FINPROD_ID AND a.SETTLE_DATE = TO_DATE(#{platDate}, 'yyyy-MM-dd') AND a.ps = #{psT02}) AS prinDayBefore,
CASE WHEN FIN_FREEZE_PLEDGE.FINPROD_ID IS NOT NULL THEN 'Y' ELSE 'N' END AS freezeFlag,
fp.REGIST_ORG AS repRegistOrg FROM ( SELECT psp.FINPROD_ID AS FINPROD_ID, psp.SEC_ACCT_ID AS SEC_ACCT_ID, SUM(NVL(DECODE(psp.HODING_TYPE, '01',psp.AMOUNT, '02',psp.AMOUNT, '03',psp.AMOUNT, '05',psp.AMOUNT, 0), 0)) AS INAMOUNT, SUM(NVL(DECODE(psp.HODING_TYPE, '04',psp.AMOUNT, 0), 0)) AS PLEDGEAMOUNT, SUM(NVL(DECODE(psp.HODING_TYPE, '06',psp.AMOUNT, '07',psp.AMOUNT, 0), 0)) AS OUTAMOUNT FROM PTL_SEC_POSITION psp WHERE psp.PORTFOLIO_ID = #{portfolioId} AND psp.CDATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND psp.HODING_TYPE IN (#{positionType01}, #{positionType02}, #{positionType03}, #{positionType04}, #{positionType05}, #{positionType06}, #{positionType07}) AND psp.CDATE = ( SELECT max(cdate) FROM PTL_SEC_POSITION tt WHERE tt.portfolio_id = psp.portfolio_id AND tt.sec_acct_id = psp.sec_acct_id AND tt.finprod_id = psp.finprod_id AND tt.CDATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND tt.branch = psp.branch AND tt.inv_aim = psp.inv_aim AND tt.hoding_type = psp.hoding_type AND tt.ccy = psp.ccy ) GROUP BY psp.FINPROD_ID, psp.SEC_ACCT_ID ) ava LEFT JOIN ( SELECT PTL_SEC_POSITION.FINPROD_ID AS FINPROD_ID, PTL_SEC_POSITION.SEC_ACCT_ID AS SEC_ACCT_ID, SUM(NVL(DECODE(HODING_TYPE, '01',AMOUNT, '02',AMOUNT, '03',AMOUNT, '05',AMOUNT, 0), 0)) AS INAMOUNT, SUM(NVL(DECODE(HODING_TYPE, '04',AMOUNT, 0), 0)) AS PLEDGEAMOUNT, SUM(NVL(DECODE(HODING_TYPE, '06',AMOUNT, '07',AMOUNT, 0), 0)) AS OUTAMOUNT FROM PTL_SEC_POSITION INNER JOIN FIN_PRODUCT ON PTL_SEC_POSITION.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeTgF01} WHERE PTL_SEC_POSITION.PORTFOLIO_ID = #{portfolioId} AND CDATE = TO_DATE(#{platDateBefore}, 'yyyy-MM-dd') AND HODING_TYPE IN (#{positionType01}, #{positionType02}, #{positionType03}, #{positionType04}, #{positionType05}, #{positionType06}, #{positionType07}) GROUP BY PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.SEC_ACCT_ID ) ava2 ON ava.FINPROD_ID = ava2.FINPROD_ID AND ava.SEC_ACCT_ID = ava2.SEC_ACCT_ID
LEFT JOIN ( SELECT psp.FINPROD_ID, SUM(DECODE(psp.HODING_TYPE,'04',-psp.AMOUNT,'06',-psp.AMOUNT,'11',-psp.AMOUNT,psp.AMOUNT)) AMOUNT FROM PTL_SEC_POSITION psp LEFT JOIN FIN_PRODUCT FPSAI ON psp.SEC_ACCT_ID = FPSAI.FINPROD_ID WHERE psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND psp.HODING_TYPE IN ( '03','04', '05','06','11','12') AND (FPSAI.FINPROD_ID is null or FPSAI.FINPROD_TYPE2 !='F28') AND psp.CDATE = ( SELECT max(cdate) FROM PTL_SEC_POSITION tt WHERE tt.portfolio_id = psp.portfolio_id AND tt.sec_acct_id = psp.sec_acct_id AND tt.finprod_id = psp.finprod_id AND tt.CDATE <= TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND tt.branch = psp.branch AND tt.inv_aim = psp.inv_aim AND tt.hoding_type = psp.hoding_type AND tt.ccy = psp.ccy ) GROUP BY psp.FINPROD_ID ) avaExt ON avaExt.FINPROD_ID = ava.FINPROD_ID LEFT JOIN ( SELECT PTL_SEC_POSITION_FLOW.FINPROD_ID, SUM(NVL(-AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION_FLOW LEFT JOIN FIN_PRODUCT FPSAI ON PTL_SEC_POSITION_FLOW.SEC_ACCT_ID = FPSAI.FINPROD_ID WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND CDATE <= TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND HODING_TYPE = '01' AND (FPSAI.FINPROD_ID is null or FPSAI.FINPROD_TYPE2 !='F28')
AND PTL_SEC_POSITION_FLOW.TRADE_ID != #{quoteId}
GROUP BY PTL_SEC_POSITION_FLOW.FINPROD_ID ) pledgeExt ON pledgeExt.FINPROD_ID = ava.FINPROD_ID
INNER JOIN STL_SEC_ACCT_INFO ON ava.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID AND STL_SEC_ACCT_INFO.TRADE_PLACE = #{tradeMarket}
INNER JOIN IBU_PORTFOLIO_ACCT_RELA ON IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID = #{portfolioId} AND IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = #{mySide} AND (IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID IS NULL OR IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE = STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE) INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID AND fp.FINPROD_TYPE2 = #{finprodTypeTgF01} LEFT JOIN FIN_PRODUCT_ADD fpa ON fp.FINPROD_ID = fpa.FINPROD_ID LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_SOURCE = #{valueSourceCBC} AND mbvi.VALUE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_SOURCE = #{valueSourceCBC} AND mbviInner.VALUE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) LEFT JOIN FIN_FREEZE_PLEDGE ON FIN_FREEZE_PLEDGE.PORTFOLIO_ID = #{portfolioId} AND FIN_FREEZE_PLEDGE.FINPROD_ID = fp.FINPROD_MARKET_ID AND FIN_FREEZE_PLEDGE.CDATE = TO_DATE(#{platDate}, 'yyyy-MM-dd') AND FIN_FREEZE_PLEDGE.ACCT_NO = ava.SEC_ACCT_ID
AND fp.REGIST_ORG = #{repRegistOrg}
AND fp.FINPROD_MARKET_ID like concat('%',concat(#{bondCode},'%'))
AND fp.IS_SUS = #{isSus}
AND fpa.IS_SEC_BOND = #{isSecBond}
AND fp.FINPROD_MARKET_ID NOT in
#{item}
AND fp.FINPROD_MARKET_ID in
#{item}

SELECT fp.FINPROD_ID AS finprodId, fp.FINPROD_MARKET_ID AS bondCode, fp.FINPROD_ABBR AS bondAbbrName, fp.IS_SUS AS isSus, fpa.IS_SEC_BOND AS isSecBond, fp.MDATE AS mdate, mbvi.NETPRICE AS netPrice, mbvi.VALUE_DATE AS valueDate, ( SELECT MAX(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = fp.FINPROD_ID AND EXERCISE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd')) AS exerciseDate, fp.REGIST_ORG AS repRegistOrg FROM FIN_PRODUCT fp LEFT JOIN FIN_PRODUCT_ADD fpa ON fp.FINPROD_ID = fpa.FINPROD_ID LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND fp.MDATE > TO_DATE(#{platDate}, 'yyyy-MM-dd') AND fp.VDATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND mbvi.VALUE_SOURCE = #{valueSourceCBC} AND mbvi.VALUE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_SOURCE = #{valueSourceCBC} AND mbviInner.VALUE_DATE <= TO_DATE(#{platDate}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) WHERE fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND fp.TRADE_MARKET = #{tradeMarket}
AND fp.REGIST_ORG = #{repRegistOrg}
AND fp.FINPROD_MARKET_ID like concat('%',concat(#{bondCode},'%'))
AND fp.IS_SUS = #{isSus}
AND fpa.IS_SEC_BOND = #{isSecBond}
AND fp.FINPROD_MARKET_ID NOT in
#{item}
AND fp.FINPROD_MARKET_ID in
#{item}
AND fp.MDATE > TO_DATE(#{platDate}, 'yyyy-MM-dd')

SELECT SUM(FPRICE_AMT) FROM (SELECT CASE REPO_PS WHEN '03' THEN SHARE_AMT*100 WHEN '04' THEN FPRICE_AMT END AS FPRICE_AMT FROM WFL_IBU_QUOTE_CREP wiqc
wiqc.ENTRUST_ID = #{entrustId}
and wiqc.WORKFLOW_ID != #{workflowId}
UNION ALL SELECT CASE REPO_PS WHEN '03' THEN SHARE_AMT*100 WHEN '04' THEN FPRICE_AMT END AS FPRICE_AMT FROM IBU_QUOTE_CREP iqc
( iqc.TRADE_STATUS NOT IN ('06','08','15') OR iqc.TRADE_STATUS IS NULL)
and iqc.ENTRUST_ID = #{entrustId}
and iqc.QUOTE_ID != #{quoteId}
)

SELECT A.ENTRUST_ID AS entrustId, A.PRICE * 100 AS price, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (A.ENTRUST_AMT -NVL(T5.FINISH_AMT, 0) - NVL(T6.FPRICE_AMT,0)) AS avaNum, C.TERM_DAYS, A.ENTRUST_STATUS, A.VDATE, A.MDATE FROM ETR_ENTRUST A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FPRICE_AMT) AS FPRICE_AMT FROM WFL_IBU_QUOTE_ETR_RE
WORKFLOW_ID != #{workflowId}
GROUP BY ENTRUST_ID) T6 ON A.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
A.ENTRUST_ID in
#{item}

SELECT IQER.QUOTE_ID, IQER.FPRICE_AMT, IQER.CB_FPRICE_AMT, IQER.SC_FPRICE_AMT, A.ENTRUST_ID AS entrustId, A.PRICE * 100 AS price, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (A.ENTRUST_AMT -NVL(T5.FINISH_AMT, 0) ) AS avaNum, C.TERM_DAYS, IQER.DEAL_FEE_AMT, IQER.SETT_FEE_AMT, IQER.CPRICE_AMT, IQER.INT_AMT, IQER.PRICE_MODEL, IQER.SHARE_AMT*100 SHARE_AMT, IQER.M_TRADE_AMT mtradeAmt, IQER.SHARE_CT_AMT FROM IBU_QUOTE_ETR_RE IQER LEFT JOIN ETR_ENTRUST A ON A.ENTRUST_ID = IQER.ENTRUST_ID INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS
QUOTE_ID != #{quoteId}
GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
IQER.QUOTE_ID = #{quoteId}

SELECT
    DECODE(COUNT(1),'1','Y','N')
FROM
    IBU_QUOTE_CREP iqc
WHERE version = '-1'

        AND  QUOTE_ROLE_TYPE = #{quoteRoleType}


        AND  REPO_PS = #{ps}


      AND  QUOTE_ID = #{quoteId}

SELECT A.ENTRUST_ID , A.PS, B.TERM_TYPE , NVL2(B.SETTLE_SPREED, CONCAT('0', B.SETTLE_SPREED + 1), NULL) settleSpreed, NVL(F.PARTY_ID, FF.PARTY_ID) AS mySide FROM ETR_ENTRUST A LEFT JOIN ETR_ENTRUST_ADD B ON B.ENTRUST_ID = A.ENTRUST_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA F ON A.PORTFOLIO_ID = F.PORTFOLIO_ID AND F.CFETS_ACCT_TYPE = '01' LEFT JOIN IBU_PORTFOLIO_ACCT_RELA FF ON A.PORTFOLIO_ID = FF.PORTFOLIO_ID AND FF.CFETS_ACCT_TYPE = '02'
A.ENTRUST_ID in
#{item}
